#include <iostream>
#include <vector>   
#include <string>

struct Request {

    std::string id;
    std::string model;
    double latency_ms;
};



int main(){
    std::vector<Request> request_container;
    request_container.reserve(2);
    request_container.push_back({"r1", "model-A", 30.0});
    request_container.push_back({"r2", "model-B", 10.0});

    const auto& req = request_container[0];
    std::cout <<request_container.size() << std::endl;
    std::cout << req.id << " "
              << req.model << " "
              << req.latency_ms << "\n";
}
